from research_helpers import *
a=ev('https://www.hella.com/en/Newsroom/Press-Releases/2026-10-08-FORVIA-HELLA-receives-major-series-orders-for-highly-integrated-EnergyCore-solutions-9847/','October 8, 2026 issuer identifies 3-in-1 HV BMS and 48 V PowerPack orders with production planned December 2027 and spring 2028, plus 12 V lithium-ion pack China nomination. Orders not current series production.')
b=ev('https://www.hella.com/microsite-electronics/en/Li-ion-battery-electronics-156.html','Manufacturer separately identifies scalable lithium-ion battery management system and BMU, CMU, insulation monitoring and current sensor components; Bender cooperation explicitly acknowledged.')
c=ev('https://www.hella.com/microsite-electronics/en/Intelligent-battery-sensor-200X-491.html','Manufacturer identifies IBS 200X passenger-car and truck configurations, with 12 V and 24 V specifications.')
d=ev('https://www.hella.com/techworld/uk/car-parts/auto-electronics/radar-sensors/','Current manufacturer aftermarket catalogue identifies 77 GHz and 24 GHz radar sensor families for ADAS/autonomous perception.')
e=ev('https://www.hella.com/en/Newsroom/Press-Releases/2025-10-14-FORVIA-HELLA-produces-its-100-millionth-radar-sensor-7281/','Issuer confirms radar series production including 77 GHz introduced in 2020. Individual vehicle-specific part numbers remain to reconcile.')
products=[]
for name,desc in [('HELLA EnergyCore 3-in-1 HV BMS','Integrated battery management, cell measurement and junction-box architecture; first series production planned December 2027.'),('HELLA EnergyCore 48 V PowerPack','Integrated low-voltage battery management and DC/DC solution; series production planned spring 2028.'),('HELLA 12 V lithium-ion battery pack','Issuer-confirmed China customer development nomination; exact model code and actual production start unverified.')]:
 products.append(p(name,desc,a,'development',typ='product',sector='energy_storage',sub='batteries',roles=['developer']))
for name,desc in [('HELLA lithium-ion battery management system','Scalable HV battery monitoring and balancing system family, distinct from newly announced 3-in-1 integration.'),('HELLA Battery Management Unit','Battery monitoring and management controller component family.'),('HELLA Cell Monitoring Unit','Battery cell measurement and balancing controller component family.'),('HELLA battery Insulation Monitoring Device','Battery insulation monitoring component developed in cooperation with Bender.'),('HELLA High Voltage Current Sensor','Shunt-based current sensor for high-voltage battery systems.')]:
 products.append(p(name,desc,b,'unknown',typ='product',sector='energy_storage',sub='batteries',roles=['developer']))
for voltage in [12,24]:products.append(p('HELLA IBS 200X '+str(voltage)+' V','Intelligent battery sensor configuration for '+str(voltage)+' V vehicle battery systems; current exact part-number availability unverified.',c,'unknown',typ='product',sector='energy_storage',sub='batteries',roles=['developer']))
for freq in [24,77]:products.append(p('HELLA '+str(freq)+' GHz radar sensor','Radar sensor family for driver assistance and automated vehicle environment perception; vehicle-specific part variants grouped.',d,'commercial',typ='product',sector='robotics',sub='autonomy_and_components',roles=['developer','manufacturer'],evidence=[d,e]))
co=company('Hella KGaA Hueck & Co',products,[a,b,c,d,e],'Initial storage-management and autonomy component families reviewed. Future EnergyCore customer orders remain development, not commercial production. Current radar manufacture supported by issuer; historical battery component catalogue availability left unknown. Need vehicle-specific part numbers, radar generations, battery disconnect/management variants, autonomous sensor technologies and separately identified proprietary ASIC products. Generic automotive electronics not automatically semiconductor products.',status='partial')
(out/'batch-0193.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
